package graph

// draftToolDeclarations are the tools that carry a draft, a problem or a human
// check, and the ones that control a task.
func draftToolDeclarations(set agentToolContext) []AgentToolDeclaration {
	main := set.main
	features := set.features
	return []AgentToolDeclaration{
		{Name: "confirm_draft", Label: "Confirm draft", Description: "Confirm the current conversation draft on the user's behalf, exactly like the confirmation card. Call it only when the user explicitly asked you to confirm, and pass their words verbatim. targetBranch must be the branch the user named. draftRevision is the draft's concurrency credential: a draft edited after you read it is refused.", Parameters: tbObject([]tbField{{"proposalVersion", tbNumber()}, {"draftRevision", tbNumber()}, {"targetBranch", tbString(nil)}, {"instruction", tbString(nil)}, {"requestId", tbString(nil)}}, []string{"proposalVersion", "draftRevision", "targetBranch", "instruction", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ConfirmDraft},
		{Name: "archive_draft", Label: "Archive draft", Description: "Archive one draft card by version: it leaves the active list but stays readable and restorable. A graph already started from that version keeps its tasks, chats, evidence and acceptance.", Parameters: tbObject([]tbField{{"proposalVersion", tbNumber()}, {"requestId", tbString(nil)}}, []string{"proposalVersion", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ArchiveDraft},
		{Name: "restore_draft", Label: "Restore draft", Description: "Restore an archived draft card by version so it returns to the active list. When nothing newer is live it becomes the current draft again and keeps its version number.", Parameters: tbObject([]tbField{{"proposalVersion", tbNumber()}, {"requestId", tbString(nil)}}, []string{"proposalVersion", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.RestoreDraft},
		{Name: "delete_draft", Label: "Delete draft", Description: "Delete one draft card by version, at the user's explicit request. It leaves both lists for good; a tombstone keeps the audit trail and the version is never reused. A graph started from that version keeps its work.", Parameters: tbObject([]tbField{{"proposalVersion", tbNumber()}, {"requestId", tbString(nil)}}, []string{"proposalVersion", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.DeleteDraft},
		{Name: "withdraw_draft", Label: "Withdraw draft", Description: "Withdraw the current unconfirmed draft so the next propose_graph starts a fresh version. The version is retired, not deleted; a draft that is not current or is confirmed is refused.", Parameters: tbObject([]tbField{{"proposalVersion", tbNumber()}, {"reason", tbOptional(tbString(nil))}, {"requestId", tbString(nil)}}, []string{"proposalVersion", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.WithdrawDraft},
		{Name: "list_problems", Label: "List execution problems", Description: "List the internal execution problems the main Agent owns. These are not user questions; inspect them before retrying, revising the graph or asking the user.", Parameters: tbObject(nil, nil), Available: main && features.Supervisor != nil && features.Supervisor.ListProblems && features.Supervisor.ResolveProblem},
		{Name: "resolve_problem", Label: "Resolve execution problem", Description: "Resolve one main-Agent-owned execution problem. retry: transient failures, or a result_noncompliant defect you can fix by re-asking the worker. acknowledge: the obstacle is cleared. respond: the worker asked a question. reconcile_usage: only when the provider cannot supply authoritative usage. escalate: only the user can decide - that opens a user question with your explanation.", Parameters: tbObject([]tbField{{"questionId", tbString(nil)}, {"action", tbString(nil)}, {"response", tbOptional(tbString(nil))}, {"proof", tbOptional(tbString(nil))}, {"requestId", tbString(nil)}}, []string{"questionId", "action", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ListProblems && features.Supervisor.ResolveProblem},
		{Name: "list_human_checks", Label: "List human acceptance checks", Description: "List the human acceptance checks of this conversation that nobody has reviewed yet; a check you already approved is not listed again. Use it when you are woken about a check, or before reporting that a task waits only on the user.", Parameters: tbObject(nil, nil), Available: main && features.Supervisor != nil && features.Supervisor.PendingHumanChecks && features.Supervisor.ReviewHumanCheck},
		{Name: "review_human_check", Label: "Review a human acceptance check", Description: "Record your look at a human acceptance check before the user is asked. approve:true means the evidence looks right and the user should be asked, with your review attached; approve:false means it should not have been raised, so send the node back for rework. This is not acceptance: the check stays open until the user passes it.", Parameters: tbObject([]tbField{{"questionId", tbString(nil)}, {"approve", tbBool()}, {"note", tbString(nil)}, {"requestId", tbString(nil)}}, []string{"questionId", "approve", "note", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.PendingHumanChecks && features.Supervisor.ReviewHumanCheck},
		{Name: "ask_user", Label: "Ask the user", Description: "Ask the user the one question whose answer changes the plan, then end this turn and wait. Write prompt and why in Markdown. Offer concise options when useful, multiple only when the choices combine; the user can always answer in their own words. The answer arrives in your next turn as a recorded fact. Use it when the project, the confirmed scope and the recorded decisions cannot settle the choice.", Parameters: tbObject([]tbField{{"prompt", tbString(nil)}, {"why", tbString(nil)}, {"options", tbOptional(tbArray(tbString(nil)))}, {"multiple", tbOptional(tbBool())}, {"requestId", tbString(nil)}}, []string{"prompt", "why", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ControlTask},
		{Name: "control_task", Label: "Control a task", Description: "Control the task you serve, or another task of the same conversation. pause soft-stops the running turn until an explicit resume; resume continues it; abandon stops the task at once and is refused while a worker lane still writes to it, so pause first; set_budget sets one node's budget as a positive token count or null for unlimited (null is what a master node normally runs with, and a finite cap must still cover the node's context reservation); steer injects a message into the turn running on a node. Every action records its reason; abandoning work the user still expects is never right.", Parameters: tbObject([]tbField{{"action", tbUnionLiteral([]string{"pause", "resume", "abandon", "set_budget", "steer"})}, {"taskId", tbOptional(tbString(nil))}, {"nodeId", tbOptional(tbString(nil))}, {"text", tbOptional(tbString(nil))}, {"tokens", tbOptional(tbUnion([]any{tbNumber(), map[string]any{"type": "null"}}))}, {"reason", tbOptional(tbString(nil))}, {"requestId", tbString(nil)}}, []string{"action", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ControlTask},
	}
}
